import java.util.Comparator;
import java.util.HashMap;
import java.util.Map;

public class SorterFactory {
    private static final Map<String, SorterBuilder<?>> REGISTRY = new HashMap<>();

    static {
        register("optimized-merge", OptimizedMergeSorterBuilder.INSTANCE);
        register("insertion", InsertionOnlySorterBuilder.INSTANCE);
    }

    public static <T extends Comparable<T>> Sorter<T> create(String algorithm) {
        SorterBuilder<T> builder = (SorterBuilder<T>) REGISTRY.get(algorithm);
        if (builder == null) {
            throw new IllegalArgumentException("Unknown sorting algorithm: " + algorithm);
        }
        return builder.build();
    }

    public static <T extends Comparable<T>> Sorter<T> create(String algorithm, SortProfile profile) {
        SorterBuilder<T> builder = (SorterBuilder<T>) REGISTRY.get(algorithm);
        if (builder == null) {
            throw new IllegalArgumentException("Unknown sorting algorithm: " + algorithm);
        }
        return builder.buildWithProfile(profile);
    }

    public static <T extends Comparable<T>> Sorter<T> createOptimized() {
        return new OptimizedMergeSort<>(SortProfile.BALANCED.create());
    }

    public static <T extends Comparable<T>> Sorter<T> createFast() {
        return new OptimizedMergeSort<>(SortProfile.SPEED.create());
    }

    public static <T extends Comparable<T>> Sorter<T> createSafe() {
        return new OptimizedMergeSort<>(SortProfile.SAFE.create());
    }

    public static <T extends Comparable<T>> Sorter<T> createDebug() {
        return new OptimizedMergeSort<>(SortProfile.DEBUG.create());
    }

    public static void register(String name, SorterBuilder<?> builder) {
        REGISTRY.put(name, builder);
    }

    public static java.util.Set<String> getAvailableAlgorithms() {
        return REGISTRY.keySet();
    }

    interface SorterBuilder<T> {
        Sorter<T> build();
        Sorter<T> buildWithProfile(SortProfile profile);
    }

    enum OptimizedMergeSorterBuilder implements SorterBuilder<Comparable> {
        INSTANCE;

        @Override
        public Sorter<Comparable> build() {
            return new OptimizedMergeSort<>(SortProfile.BALANCED.create());
        }

        @Override
        public Sorter<Comparable> buildWithProfile(SortProfile profile) {
            return new OptimizedMergeSort<>(profile.create());
        }
    }

    enum InsertionOnlySorterBuilder implements SorterBuilder<Comparable> {
        INSTANCE;

        @Override
        public Sorter<Comparable> build() {
            SortConfiguration<Comparable> config = SortConfiguration.<Comparable>builder()
                    .withComparator(Comparable::compareTo)
                    .withThreshold(Integer.MAX_VALUE)
                    .build();
            return new OptimizedMergeSort<>(config, new InsertionSortStrategy<>(Comparable::compareTo, null));
        }

        @Override
        public Sorter<Comparable> buildWithProfile(SortProfile profile) {
            return build();
        }
    }
}

